<script setup lang="ts">
import {onMounted,ref} from 'vue';import {doctorApi,settingsApi,type DoctorReport,type SettingSection} from '@/lib/api';import Card from '@/components/ui/Card.vue';import Button from '@/components/ui/Button.vue';import Badge from '@/components/ui/Badge.vue';import {useToast} from '@/composables/useToast';const report=ref<DoctorReport|null>(null);const sources=ref<Record<string,unknown>>({});const {toast}=useToast();const checks=ref<Record<string,string>>({});onMounted(async()=>{[report.value,sources.value]=await Promise.all([doctorApi.diagnose(),settingsApi.getSection('sources')])});async function test(provider:string){try{const r=await settingsApi.testProvider(provider);checks.value[provider]=r.message;toast(`${provider}：${r.message}`,r.valid?'success':'error')}catch(e){toast(e instanceof Error?e.message:'检测失败','error')}}
</script>
<template><div class="space-y-5"><div><h2 class="text-xl font-semibold">双源雷达</h2><p class="text-sm text-muted">搜索源配置、连通性测试与运行健康</p></div><div class="grid gap-4 sm:grid-cols-2"><Card v-for="provider in ['115','quark','telegram','manual']" :key="provider" class="p-4"><div class="flex items-center justify-between"><h3 class="font-semibold">{{provider}}</h3><Badge :tone="checks[provider]?'good':'muted'">{{checks[provider]??'未检测'}}</Badge></div><p class="my-3 break-all text-xs text-muted">{{sources[provider]??'由 sources 配置分组管理'}}</p><Button variant="outline" size="sm" @click="test(provider)">测试连通</Button></Card></div><Card class="p-5"><h3 class="mb-3 font-semibold">诊断状态</h3><pre class="overflow-auto whitespace-pre-wrap text-xs text-muted">{{JSON.stringify(report,null,2)}}</pre></Card></div></template>